mapper.select:
SELECT A.STATUS status, A.STATUS statusName, A.CCY_ORIGINAL ccyOriginal, A.CCY_ORIGINAL ccyOriginalName, A.CCY_CONVERT ccyConvert, A.CCY_CONVERT ccyConvertName, A.PUBLISH_DATE publishDate, A.EXCHANGE_PRICE exchangePrice, A.EXCHANGE_PRICE exchangeRate FROM CHB_MST_EXCHANGE_INFO A
#{ccyOriginal}
#{ccyConvert}
AND A.PUBLISH_DATE >= STR_TO_DATE(#{publishDateStart,jdbcType=DATE},'%Y-%m-%d')
AND A.PUBLISH_DATE <= STR_TO_DATE(#{publishDateEnd,jdbcType=DATE},'%Y-%m-%d')
#{key,jdbcType=VARCHAR}
ORDER BY A.PUBLISH_DATE DESC

SELECT A.STATUS status, A.CCY_ORIGINAL ccyOriginal, A.CCY_CONVERT ccyConvert, DATE_FORMAT(A.PUBLISH_DATE,'%Y-%m-%d') publishDate, A.EXCHANGE_PRICE exchangePrice, A.EXCHANGE_PRICE exchangeRate FROM CHB_MST_EXCHANGE_INFO A
A.CCY_ORIGINAL = #{ccyOriginal,jdbcType=VARCHAR}
AND A.CCY_CONVERT = #{ccyConvert,jdbcType=VARCHAR}
AND DATE_FORMAT(A.PUBLISH_DATE, '%Y-%m-%d') = DATE_FORMAT(#{publishDate,jdbcType=DATE}, '%Y-%m-%d') AND A.STATUS=#{status,jdbcType=VARCHAR}

SELECT
	count(1)
from CHB_MST_EXCHANGE_INFO mei
where mei.CCY_ORIGINAL=#{ccyOriginal}
and mei.CCY_CONVERT= #{ccyConvert}

and DATE_FORMAT(mei.PUBLISH_DATE, '%Y-%m-%d') = #{publishDate}
and mei.STATUS='E'

mapper.delete:
delete CHB_MST_EXCHANGE_INFO
where CCY_ORIGINAL = #{ccyOriginal,jdbcType=VARCHAR}
	and CCY_CONVERT = #{ccyConvert,jdbcType=VARCHAR}
	and STATUS ='E'

	and DATE_FORMAT(PUBLISH_DATE, '%Y-%m-%d') = DATE_FORMAT(#{publishDate,jdbcType=DATE}, '%Y-%m-%d')
